from batch07 import *
start('acl','ACL — kolejność, zakres i diagnostyka','5.6',['https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec_data_acl/configuration/15-s/sec-data-acl-15-s-book/sec-create-ip-al-filter.html','https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec_data_acl/configuration/15-s/sec-data-acl-15-s-book/sec-refine-ip-al.html','https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/sec_data_acl/configuration/15-e/sec-data-acl-15-e-book/sec-acl-seq-num.html'],True)
q('Reguła zasłonięta','ACL zawiera 10 permit ip any any, a potem 20 deny tcp any host 10.0.0.10 eq 22. Czy drugi wpis zablokuje SSH do tego hosta?','Nie, pasujący ruch został już dopuszczony przez wpis 10',['Tak, deny zawsze wygrywa z permit|ACL stosuje kolejność, nie globalne pierwszeństwo deny.','Tak, wyższy numer sekwencji ma priorytet|Niższy numer jest sprawdzany wcześniej.','Tylko jeśli host odpowiada pingiem|ICMP nie zmienia zasady pierwszego dopasowania.'],'Pierwsze dopasowanie kończy ocenę pakietu; szerokie permit może zasłonić szczegółowy zakaz.')
q('TCP established','Co sprawdza klasyczne słowo established w rozszerzonej ACL IPv4 dla TCP?','Ustawienie bitu ACK lub RST',['Pełną tabelę stanów wszystkich sesji|Nie jest pełnym stateful firewallem.','Zakończenie uwierzytelniania SSH|ACL nie rozumie takiego stanu aplikacji.','Czy ruch używa UDP|To opcja dla TCP.'],'Dopasowanie flag nie potwierdza, że pakiet należy do legalnej, wcześniej śledzonej sesji.')
c('Ponumeruj od nowa','ACL WEB ma być ponumerowana od 100 z odstępem 10, bez zmiany kolejności reguł.','R1(config)# ip access-list resequence WEB {{b0}} {{b1}}',['100','10'],'Resequence zmienia numery, zachowując porządek wpisów; ułatwia dalsze wstawianie.')
q('Źródłowy port odpowiedzi','Serwer odpowiada z TCP 443 do efemerycznego portu klienta. W którym miejscu ACL wpisujesz eq 443, aby sprawdzić port serwera w odpowiedzi?','Po adresie źródłowym, przed adresem docelowym',['Wyłącznie po adresie docelowym|W odpowiedzi serwer ma port źródłowy 443.','Zamiast wildcard źródła|Wildcard dopasowuje adres, nie port.','Przed słowem tcp|Składnia portu znajduje się przy odpowiedniej stronie adresowej.'],'Kierunek ruchu odwraca role adresów i portów; trzeba czytać konkretny pakiet.')
c('DNS do jednego resolvera','W nazwanej ACL zezwól na UDP z 10.20.0.0/24 do 192.0.2.53, docelowy port 53. Wpisz wildcard i port.','R1(config-ext-nacl)# 10 permit udp 10.20.0.0 {{b0}} host 192.0.2.53 eq {{b1}}',[(['0.0.0.255'],'ipv4'),'53'],'Dopasowujemy port docelowy zapytania. Pełna polityka DNS powinna rozważyć także TCP zgodnie z wymaganiami.')
q('Wildcard nie jest maską','Który wildcard obejmuje dokładnie 10.8.0.0/23?','0.0.1.255',['255.255.254.0|To maska podsieci, nie wildcard.','0.0.0.255|Ten wildcard obejmuje tylko /24, czyli połowę wymaganego zakresu.','0.0.3.255|To zakres odpowiadający /22 przy prawidłowej granicy.'],'Wildcard jest bitowym dopełnieniem maski dla tego ciągłego prefiksu.')
q('Dwa kierunki','ACL inbound na interfejsie LAN dopuszcza zapytanie klienta. Czy sama ta ACL automatycznie filtruje odpowiedź wychodzącą tym samym interfejsem?','Nie, inbound dotyczy wejścia do routera tym interfejsem',['Tak, każda ACL jest dwukierunkowa|Kierunek przypisania ma znaczenie.','Tak, jeśli używa numerowanej listy|Rodzaj nazwy nie zmienia kierunku.','Tak, ponieważ TCP ma handshake|Handshake nie zmienia przypisania ACL.'],'Przepływ odpowiedzi wymaga przeanalizowania jej własnej drogi i właściwych filtrów.')
q('Wildcard 0.0.0.0','Jaką część adresu porównuje wildcard 0.0.0.0?','Wszystkie bity, czyli dokładny adres hosta',['Żadnego bitu|Ignorowanie wszystkich bitów odpowiada 255.255.255.255.','Tylko pierwszy oktet|Zera obejmują wszystkie cztery oktety.','Tylko port TCP|Wildcard odnosi się do adresu IP.'],'Zero w wildcard wymaga zgodności odpowiadającego bitu.')
c('Dwa transporty DNS','W ACL DNS-OUT dopuść z 10.30.0.0/24 zapytania UDP i TCP do jednego resolvera 192.0.2.53 na port 53.','R1(config-ext-nacl)# 10 permit {{b0}} 10.30.0.0 0.0.0.255 host 192.0.2.53 eq {{b1}}\nR1(config-ext-nacl)# 20 permit {{b2}} 10.30.0.0 0.0.0.255 host 192.0.2.53 eq 53',['udp','53','tcp'],'DNS może korzystać z UDP i TCP; ograniczenie do jednego transportu może dać częściowo działającą usługę.')
q('Licznik hitów','Wpis ACL ma 200 matches. Czy sam ten odczyt dowodzi, że obecny test właśnie dopasował tę regułę?','Nie, potrzebny jest przyrost licznika w czasie testu',['Tak, każdy licznik jest zerowany co sekundę|Nie ma takiej ogólnej zasady.','Tak, 200 oznacza kod HTTP sukcesu|To liczba dopasowań, nie odpowiedź HTTP.','Nie, ACL nigdy nie mają liczników|Licznik jest przydatny, ale wymaga kontekstu czasowego.'],'Porównuj stan przed i po kontrolowanym teście, uwzględniając inny ruch.')
c('Wyjątek przed blokadą','ACL MGMT ma wolną sekwencję 15 przed szerszym deny na 20. Wstaw pod 15 pozwolenie TCP z 10.99.0.5 do 10.99.0.10 na SSH.','R1(config-ext-nacl)# {{b0}} permit tcp host {{b1}} host 10.99.0.10 eq {{b2}}',['15',(['10.99.0.5'],'ipv4'),'22'],'Wyjątek musi znajdować się przed zakazem, który inaczej dopasowałby ten sam pakiet.')
q('Samo utworzenie ACL','Utworzono poprawną ACL, ale nie użyto jej na interfejsie ani w innej funkcji. Co wynika z samej definicji?','Nie zaczyna automatycznie filtrować całego ruchu routera',['Natychmiast blokuje wszystkie porty|Definicja nie jest globalnym przypisaniem.','Automatycznie działa na VTY|VTY wymaga właściwego użycia listy.','Automatycznie staje się polityką NAT|NAT wymaga odwołania w konfiguracji.'],'Lista jest obiektem, którego znaczenie operacyjne wynika z miejsca zastosowania.')
q('ICMP echo a echo-reply','Chcesz dopasować żądanie ping wysyłane przez klienta. Jaki typ ICMP IPv4 odpowiada temu kierunkowi?','echo',['echo-reply|To odpowiedź na żądanie.','time-exceeded|To komunikat o przekroczeniu czasu/TTL.','unreachable|To komunikat o nieosiągalności.'],'Żądanie i odpowiedź mają różne typy ICMP, więc politykę trzeba zaprojektować dla obu kierunków.')
q('Brak transportu w fragmencie','Dlaczego filtrowanie wyłącznie według portu TCP wymaga uwagi przy fragmentacji IPv4?','Fragmenty inne niż pierwszy nie zawierają typowo nagłówka TCP',['Każdy fragment ma pełną nową sesję TCP|Fragmentacja IP nie tworzy sesji TCP.','Fragmenty zawsze zmieniają protokół na UDP|Nie zmieniają w ten sposób protokołu.','IPv4 nigdy nie może być fragmentowany|IPv4 obsługuje fragmentację.'],'Semantykę ACL i obsługę fragmentów należy sprawdzić dla konkretnej platformy; nie zakładać pełnych pól L4 w każdym fragmencie.')
c('Kontrolowany ping','W nowej ACL PING-ONLY dopuść tylko żądania ICMP echo z 10.70.0.5 do 10.70.1.5 i zastosuj listę inbound na G0/0.','R1(config)# ip access-list extended PING-ONLY\nR1(config-ext-nacl)# 10 permit {{b0}} host 10.70.0.5 host 10.70.1.5 {{b1}}\nR1(config-ext-nacl)# exit\nR1(config)# interface GigabitEthernet0/0\nR1(config-if)# ip access-group PING-ONLY {{b2}}',['icmp','echo','in'],'Niejawny deny odrzuci pozostały ruch w tym kierunku. Droga odpowiedzi wymaga osobnej oceny.')
q('Permit przed końcem','Nowa ACL ma tylko permit tcp any host 192.0.2.10 eq 443. Co dzieje się z niedopasowanym ruchem IPv4 na filtrowanym wejściu?','Zostaje odrzucony przez niejawny deny',['Jest automatycznie dopuszczony|ACL nie ma domyślnego permit dla reszty.','Jest przekierowany do DNS|ACL nie wykonuje takiego przekierowania.','Jest zamieniony na HTTPS|Filtr nie zmienia protokołu aplikacji.'],'Jeśli wymagasz zachowania pozostałego ruchu, musisz jawnie zaprojektować odpowiednie pozwolenia.')
c('Odepnij i zbadaj listę','W labie zdejmij ACL TEST-IN z wejścia G0/0 bez kasowania jej definicji, a potem pokaż reguły tej listy.','R1(config)# interface GigabitEthernet0/0\nR1(config-if)# no ip {{b0}} TEST-IN {{b1}}\nR1(config-if)# end\nR1# show ip {{b2}} TEST-IN',['access-group','in','access-lists'],'Usunięcie przypisania i usunięcie definicji to różne operacje; lista może być używana także gdzie indziej.')
q('Szeroki wildcard','Czy wpis źródła 10.0.0.0 0.255.255.255 obejmuje 10.250.7.9?','Tak',['Nie, tylko 10.0.0.0|Pozostałe trzy oktety są ignorowane przez wildcard.','Nie, bo ostatni oktet musi być zerem|Maska wildcard nie wymaga tu zera.','Tylko jeśli ma port TCP 10|Źródłowy wildcard nie określa portu transportowego.'],'Pierwszy oktet musi być 10; wszystkie bity pozostałych oktetów są dowolne.')
end()
